422		mustHandoff(t, s, "R5", "站点C", "站点B", []string{"P003"}, tClock(2026, 10, 5, 12, 0))
423		before, err := os.ReadFile(path)
424		if err != nil {
425			t.Fatal(err)
426		}
427	
428		cases := []struct {
429			name    string
430			req     string
431			handoff string
432			reason  string
433		}{
434			{"原交接不存在", "RT1", "NOPE", "错发"},
435			{"批次含已离开目的站的包裹", "RT2", "R1", "错发"},
436			{"回到同一站点但不能退回旧交接", "RT3", "R3", "错发"},
437		}
438		for _, c := range cases {
439			t.Run(c.name, func(t *testing.T) {
440				if _, _, err := s.Return(c.req, c.handoff, c.reason, tClock(2026, 10, 5, 13, 0)); err == nil {
441					t.Fatal("条件不满足时整批退回必须失败")
442				}
443				after, _ := os.ReadFile(path)
444				if string(after) != string(before) {
445					t.Fatal("失败退回不得写入数据文件")
446				}
447				if _, ok := s.data.Returns[c.req]; ok {
448					t.Fatalf("失败的首次退回不得占用退回请求号 %q", c.req)
449				}
450			})
451		}
452	
453		// 包裹归属与轨迹均未变。
454		p1, _ := s.Query("P001")
455		if p1.Station != "站点B" || len(p1.Trail) != 2 {
456			t.Fatalf("失败退回不得改动 P001: %+v", p1)
457		}
458		p3, _ := s.Query("P003")
459		if p3.Station != "站点B" || len(p3.Trail) != 4 {
460			t.Fatalf("失败退回不得改动 P003: %+v", p3)
461		}
462	
463		// 失败的请求号纠正后可复用：先把 P002 交回 B 不满足（最后一条须为 R1），
464		// 改用未退回的 R3 也不行；这里验证失败号 RT2 可用于一次新的失败重试后仍不占用。
465		if _, _, err := s.Return("RT2", "R3", "错发", tClock(2026, 10, 5, 13, 30)); err == nil {
466			t.Fatal("R3 的包裹最后一条流转不是 R3，应失败")
467		}
468		if _, ok := s.data.Returns["RT2"]; ok {
469			t.Fatal("再次失败的退回仍不得占用请求号 RT2")
470		}
471	}
