508		mustHandoff(t, s, "R2", "站点A", "站点C", []string{"P001", "P002"}, tClock(2026, 10, 5, 13, 0))
509		replay, replayed2, err := s.Return("RT1", "R1", "错发站点", tClock(2026, 10, 5, 14, 0))
