526			t.Fatal("换原因必须报冲突")
527		}
528		saved := s.data.Returns["RT1"]
529		if saved != first || saved.Handoff != "R1" || saved.Reason != "错发站点" {
530			t.Fatalf("冲突提交不得改动已有退回结果: %+v", saved)
531		}
