593	func TestCorruptReturnDataRejected(t *testing.T) {
594		dir := t.TempDir()
595		path := filepath.Join(dir, "ledger.json")
596	
597		parcel := `"id":"P1","station":"A","status":"在站","registered":"2026-10-05T09:00:00Z"`
598		goodTrail := `"op":"收件","station":"A","time":"2026-10-05T09:00:00Z"`
599		cases := map[string]string{
